#include "GroceryStore.h"
#include <iostream>
#include <iomanip>
#include <limits>
#include <stdexcept>
using namespace std;

namespace {
void clearInput(){ cin.clear(); cin.ignore(numeric_limits<streamsize>::max(),'\n'); }
int readInt(const string& prompt){ int x; while(true){ cout<<prompt; if(cin>>x){cin.ignore(numeric_limits<streamsize>::max(),'\n'); return x;} cout<<"Invalid input. Enter a number.\n"; clearInput(); } }
double readDouble(const string& prompt){ double x; while(true){ cout<<prompt; if(cin>>x){cin.ignore(numeric_limits<streamsize>::max(),'\n'); return x;} cout<<"Invalid input. Enter a number.\n"; clearInput(); } }
string readText(const string& prompt){ string x; do{ cout<<prompt; getline(cin,x); if(x.empty()) cout<<"Input cannot be empty.\n"; }while(x.empty()); return x; }
}

GroceryStore::GroceryStore(): productCount(0),customerCount(0),supplierCount(0),saleCount(0),productCapacity(5),customerCapacity(5),supplierCapacity(5),saleCapacity(10),nextSaleId(1){ products=new Product[productCapacity]; customers=new Customer[customerCapacity]; suppliers=new Supplier[supplierCapacity]; sales=new Sale[saleCapacity]; }
GroceryStore::~GroceryStore(){ delete[] products; delete[] customers; delete[] suppliers; delete[] sales; }
void GroceryStore::resizeProducts(){int c=productCapacity*2; Product* a=new Product[c]; for(int i=0;i<productCount;i++)a[i]=products[i]; delete[] products;products=a;productCapacity=c;}
void GroceryStore::resizeCustomers(){int c=customerCapacity*2; Customer* a=new Customer[c]; for(int i=0;i<customerCount;i++)a[i]=customers[i]; delete[] customers;customers=a;customerCapacity=c;}
void GroceryStore::resizeSuppliers(){int c=supplierCapacity*2; Supplier* a=new Supplier[c]; for(int i=0;i<supplierCount;i++)a[i]=suppliers[i]; delete[] suppliers;suppliers=a;supplierCapacity=c;}
void GroceryStore::resizeSales(){int c=saleCapacity*2; Sale* a=new Sale[c]; for(int i=0;i<saleCount;i++)a[i]=sales[i]; delete[] sales;sales=a;saleCapacity=c;}
int GroceryStore::findProductIndex(int id) const {for(int i=0;i<productCount;i++)if(products[i].getId()==id)return i;return -1;}
int GroceryStore::findCustomerIndex(int id) const {for(int i=0;i<customerCount;i++)if(customers[i].getId()==id)return i;return -1;}
int GroceryStore::findSupplierIndex(int id) const {for(int i=0;i<supplierCount;i++)if(suppliers[i].getId()==id)return i;return -1;}
void GroceryStore::addProduct(){ try{int id=readInt("Product ID: "); if(id<=0||findProductIndex(id)>=0)throw invalid_argument("ID must be positive and unique."); string n=readText("Product Name: "); double p=readDouble("Price: "); int s=readInt("Stock: "); if(p<0||s<0)throw invalid_argument("Price and stock cannot be negative."); if(productCount==productCapacity)resizeProducts(); products[productCount++]=Product(id,n,p,s); cout<<"Product added successfully.\n";}catch(const exception&e){cout<<"Error: "<<e.what()<<'\n';}}
void GroceryStore::addCustomer(){try{int id=readInt("Customer ID: ");if(id<=0||findCustomerIndex(id)>=0)throw invalid_argument("ID must be positive and unique.");string n=readText("Customer Name: ");string p=readText("Phone: ");if(customerCount==customerCapacity)resizeCustomers();customers[customerCount++]=Customer(id,n,p);cout<<"Customer added successfully.\n";}catch(const exception&e){cout<<"Error: "<<e.what()<<'\n';}}
void GroceryStore::addSupplier(){try{int id=readInt("Supplier ID: ");if(id<=0||findSupplierIndex(id)>=0)throw invalid_argument("ID must be positive and unique.");string n=readText("Supplier Name: ");string p=readText("Phone: ");if(supplierCount==supplierCapacity)resizeSuppliers();suppliers[supplierCount++]=Supplier(id,n,p);cout<<"Supplier added successfully.\n";}catch(const exception&e){cout<<"Error: "<<e.what()<<'\n';}}
void GroceryStore::displayProducts() const{cout<<"\nPRODUCTS\n"<<left<<setw(10)<<"ID"<<setw(22)<<"NAME"<<right<<setw(12)<<"PRICE"<<setw(10)<<"STOCK"<<'\n';cout<<string(54,'-')<<'\n';for(int i=0;i<productCount;i++)products[i].display();if(productCount==0)cout<<"No products found.\n";}
void GroceryStore::displayCustomers() const{cout<<"\nCUSTOMERS\n"<<left<<setw(10)<<"ID"<<setw(25)<<"NAME"<<setw(18)<<"PHONE"<<setw(12)<<"TYPE"<<'\n';cout<<string(65,'-')<<'\n';for(int i=0;i<customerCount;i++)customers[i].display();if(customerCount==0)cout<<"No customers found.\n";}
void GroceryStore::displaySuppliers() const{cout<<"\nSUPPLIERS\n"<<left<<setw(10)<<"ID"<<setw(25)<<"NAME"<<setw(18)<<"PHONE"<<setw(12)<<"TYPE"<<'\n';cout<<string(65,'-')<<'\n';for(int i=0;i<supplierCount;i++)suppliers[i].display();if(supplierCount==0)cout<<"No suppliers found.\n";}
void GroceryStore::displaySales() const{cout<<"\nSALES\n"<<left<<setw(10)<<"SALE ID"<<setw(12)<<"PRODUCT"<<setw(12)<<"CUSTOMER"<<setw(10)<<"QTY"<<right<<setw(12)<<"TOTAL"<<'\n';cout<<string(56,'-')<<'\n';for(int i=0;i<saleCount;i++)sales[i].display();if(saleCount==0)cout<<"No sales found.\n";}
void GroceryStore::searchRecord() const{int type=readInt("1. Product  2. Customer  3. Supplier\nChoose: ");int id=readInt("Enter ID: ");if(type==1){int i=findProductIndex(id);if(i<0)cout<<"Product not found.\n";else{cout<<"Found:\n";products[i].display();}}else if(type==2){int i=findCustomerIndex(id);if(i<0)cout<<"Customer not found.\n";else customers[i].display();}else if(type==3){int i=findSupplierIndex(id);if(i<0)cout<<"Supplier not found.\n";else suppliers[i].display();}else cout<<"Invalid choice.\n";}
void GroceryStore::updateRecord(){int type=readInt("1. Product  2. Customer\nChoose: ");int id=readInt("Enter ID: ");try{if(type==1){int i=findProductIndex(id);if(i<0){cout<<"Product not found.\n";return;}string n=readText("New name: ");double p=readDouble("New price: ");int s=readInt("New stock: ");products[i].setName(n);products[i].setPrice(p);products[i].setStock(s);cout<<"Product updated.\n";}else if(type==2){int i=findCustomerIndex(id);if(i<0){cout<<"Customer not found.\n";return;}customers[i].setName(readText("New name: "));customers[i].setPhone(readText("New phone: "));cout<<"Customer updated.\n";}else cout<<"Invalid choice.\n";}catch(const exception&e){cout<<"Error: "<<e.what()<<'\n';}}
void GroceryStore::deleteRecord(){int type=readInt("1. Product  2. Customer  3. Supplier\nChoose: ");int id=readInt("Enter ID: ");if(type==1){int i=findProductIndex(id);if(i<0){cout<<"Product not found.\n";return;}for(;i<productCount-1;i++)products[i]=products[i+1];productCount--;cout<<"Product deleted.\n";}else if(type==2){int i=findCustomerIndex(id);if(i<0){cout<<"Customer not found.\n";return;}for(;i<customerCount-1;i++)customers[i]=customers[i+1];customerCount--;cout<<"Customer deleted.\n";}else if(type==3){int i=findSupplierIndex(id);if(i<0){cout<<"Supplier not found.\n";return;}for(;i<supplierCount-1;i++)suppliers[i]=suppliers[i+1];supplierCount--;cout<<"Supplier deleted.\n";}else cout<<"Invalid choice.\n";}
void GroceryStore::sellProduct(){try{int cid=readInt("Customer ID: ");if(findCustomerIndex(cid)<0)throw invalid_argument("Customer not found.");int pid=readInt("Product ID: ");int pi=findProductIndex(pid);if(pi<0)throw invalid_argument("Product not found.");int qty=readInt("Quantity: ");if(qty<=0)throw invalid_argument("Quantity must be positive.");if(products[pi].getStock()<qty)throw invalid_argument("Insufficient stock.");if(saleCount==saleCapacity)resizeSales();sales[saleCount]=Sale(nextSaleId++,pid,cid,qty,products[pi].getPrice());products[pi].updateStock(-qty);generateBill(saleCount);saleCount++;cout<<"Transaction completed successfully.\n";}catch(const exception&e){cout<<"Transaction failed: "<<e.what()<<'\n';}}
void GroceryStore::generateBill(int i) const{const Sale&s=sales[i];int pi=findProductIndex(s.getProductId());int ci=findCustomerIndex(s.getCustomerId());cout<<"\n========================================\n              GROCERY BILL\n========================================\n";cout<<"Sale ID     : "<<s.getSaleId()<<'\n';cout<<"Customer    : "<<(ci>=0?customers[ci].getName():"Unknown")<<'\n';cout<<"Product     : "<<(pi>=0?products[pi].getName():"Unknown")<<'\n';cout<<"Unit Price  : Rs. "<<(pi>=0?products[pi].getPrice():0)<<'\n';cout<<"Quantity    : "<<s.getQuantity()<<'\n';cout<<"----------------------------------------\n";cout<<"TOTAL       : Rs. "<<fixed<<setprecision(2)<<s.getTotal()<<'\n';cout<<"========================================\n";}
void GroceryStore::showReport() const{double revenue=0;for(int i=0;i<saleCount;i++)revenue+=sales[i].getTotal();cout<<"\n========== STORE REPORT ==========\n";cout<<"Products  : "<<productCount<<'\n';cout<<"Customers : "<<customerCount<<'\n';cout<<"Suppliers : "<<supplierCount<<'\n';cout<<"Sales     : "<<saleCount<<'\n';cout<<"Revenue   : Rs. "<<fixed<<setprecision(2)<<revenue<<'\n';cout<<"==================================\n";}
void GroceryStore::addRecordMenu(){int c=readInt("1. Product  2. Customer  3. Supplier\nChoose: ");if(c==1)addProduct();else if(c==2)addCustomer();else if(c==3)addSupplier();else cout<<"Invalid choice.\n";}
void GroceryStore::displayRecordMenu() const{int c=readInt("1. Products  2. Customers  3. Suppliers  4. Sales\nChoose: ");if(c==1)displayProducts();else if(c==2)displayCustomers();else if(c==3)displaySuppliers();else if(c==4)displaySales();else cout<<"Invalid choice.\n";}
void GroceryStore::loadData(){try{productCount=fileManager.loadProducts(products,productCapacity);customerCount=fileManager.loadCustomers(customers,customerCapacity);supplierCount=fileManager.loadSuppliers(suppliers,supplierCapacity);saleCount=fileManager.loadSales(sales,saleCapacity);for(int i=0;i<saleCount;i++)if(sales[i].getSaleId()>=nextSaleId)nextSaleId=sales[i].getSaleId()+1;cout<<"Data loaded successfully.\n";}catch(const exception&e){cout<<"Load warning: "<<e.what()<<'\n';}}
void GroceryStore::saveData() const{try{fileManager.saveProducts(products,productCount);fileManager.saveCustomers(customers,customerCount);fileManager.saveSuppliers(suppliers,supplierCount);fileManager.saveSales(sales,saleCount);cout<<"Data saved successfully.\n";}catch(const exception&e){cout<<"Save error: "<<e.what()<<'\n';}}
void GroceryStore::runSaveLoadMenu(){int c=readInt("1. Save Data  2. Load Data\nChoose: ");if(c==1)saveData();else if(c==2)loadData();else cout<<"Invalid choice.\n";}
